                    key={r.slug}
                    href={`/blog/${r.slug}`}
                    style={{ textDecoration: "none", color: "inherit" } as React.CSSProperties}
                  >
                    <article
                      style={{
                        background: BRAND.white,
                        borderRadius: 14,
                        overflow: "hidden",
                        boxShadow: SHADOW.soft,
                        border: `1px solid ${BRAND.borderSoft}`,
                        height: "100%",
                      } as React.CSSProperties}
                    >
                      <div
                        style={{ height: 140, background: r.gradient } as React.CSSProperties}
                      />
                      <div style={{ padding: 22 } as React.CSSProperties}>
                        <h3
                          style={{
                            fontFamily: FONT.serif,
                            fontSize: 20,
                            color: BRAND.onyx,
                            marginBottom: 10,
                            letterSpacing: "-0.015em",
                            lineHeight: 1.25,
                          } as React.CSSProperties}
                        >
                          {r.title}
                        </h3>
                        <p
                          style={{
                            fontFamily: FONT.sans,
                            fontSize: 13,
                            color: BRAND.stoneDark,
                            lineHeight: 1.55,
                            marginBottom: 12,
                          } as React.CSSProperties}
                        >
                          {r.excerpt}
                        </p>
                        <div
                          style={{
                            fontFamily: FONT.sans,
                            fontSize: 12,
                            color: BRAND.stoneLight,
                            display: "flex",
                            alignItems: "center",
                            gap: 8,
                          } as React.CSSProperties}
                        >
                          <span>{r.author.name}</span>
                          <span>·</span>
                          <span>{r.readTime}</span>
                        </div>
                      </div>
                    </article>
                  </Link>
                ))}
              </div>
            </div>
          </section>
        )}

        <CTASection
          badge="Get the next one"
          headline="Subscribe for the studio playbook."
          italicWord="playbook"
          subhead="One email per month. Studio operations, compliance updates, the maths nobody else writes."
          primaryCTA={{ label: "Start a 14-day trial", href: "https://inkos.up.railway.app/signup" }}
          secondaryCTA={{ label: "Talk to us", href: "/book-a-demo", icon: "play" }}
        />
      </main>
      <Footer />
    </div>
  );
}

